package com.lumix.admin.control;
import java.time.Instant; import java.util.Objects;
/** P27 RBAC policy，將 session、MFA、operation 明確輸入以維持 deterministic、預設拒絕。 */
public final class AdminAuthorizationPolicy { public AdminAuthorizationDecision evaluate(AdminSessionEvidence session,AdminOperation operation,Instant evaluatedAt){session=Objects.requireNonNull(session,"session");operation=Objects.requireNonNull(operation,"operation");evaluatedAt=Objects.requireNonNull(evaluatedAt,"evaluatedAt");if(!evaluatedAt.isBefore(session.expiresAt()))return AdminAuthorizationDecision.SESSION_EXPIRED_REJECTED;if(!session.mfaVerified())return AdminAuthorizationDecision.MFA_REQUIRED_REJECTED;AdminRole required=operation==AdminOperation.READ_OPERATIONAL_VIEW?AdminRole.READ_ONLY_OPERATOR:operation==AdminOperation.REQUEST_CONTROLLED_ACTION?AdminRole.SENSITIVE_ACTION_REVIEWER:AdminRole.SECURITY_AUDITOR;return session.roles().contains(required)?AdminAuthorizationDecision.ALLOWED:AdminAuthorizationDecision.ROLE_NOT_ALLOWED_REJECTED;} }
